    fun find(query:String):KnowledgeEntry? {
        val n=V5TextPipeline.normalize(query)
        val stems=RussianMorphology.stemSet(n)
        return entries.maxByOrNull { e ->
            e.keywords.count { k -> n.contains(k) || stems.contains(RussianMorphology.stem(k)) }
        }?.takeIf { e -> e.keywords.any { k -> n.contains(k) || stems.contains(RussianMorphology.stem(k)) } }
    }

    fun all():List<KnowledgeEntry> = entries
